#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = path.join(ROOT, 'output');
const BLOCK = '**** YD001 SOURCE BLOCK ****';
const ENG = '**** ENGLISH ****';
const END = '**** END BLOCK ****';

function patchFile(rel, slug, T) {
  const fp = path.join(OUT, rel);
  const s = fs.readFileSync(fp, 'utf8');
  const applied = new Set();
  const parts = s.split(BLOCK);
  const out = parts.map((block, i) => {
    if (i === 0) return block;
    const slugM = block.match(/^\s*slug: (.+)$/m);
    const seifM = block.match(/^\s*seif: (.+)$/m);
    const markerM = block.match(/^\s*marker: (.+)$/m);
    if (!slugM || slugM[1].trim() !== slug) return BLOCK + block;
    const seif = seifM[1].trim();
    const marker = markerM ? markerM[1].trim() : 'main';
    const key = `${seif}#${marker}`;
    if (!(key in T)) return BLOCK + block;
    const enStart = block.indexOf(ENG);
    const enEnd = block.indexOf(END);
    if (enStart < 0 || enEnd < 0) throw new Error(`ENGLISH/END missing: ${rel} ${key}`);
    const before = block.slice(0, enStart + ENG.length + 1);
    const after = block.slice(enEnd);
    const text = T[key].endsWith('\n') ? T[key] : T[key] + '\n';
    applied.add(key);
    return BLOCK + before + text + after;
  });
  const missing = Object.keys(T).filter((k) => !applied.has(k));
  if (missing.length) throw new Error(`Keys not found in ${rel}: ${missing.join(', ')}`);
  fs.writeFileSync(fp, out.join(''), 'utf8');
  console.log(`OK ${rel} (${applied.size} blocks)`);
}

// --- mechaber (6) ---
patchFile('siman_023/mechaber/part-001.txt', 'mechaber', {
  '1#main': `The laws of shehiyah in shechitah. In it are 6 seifim. Any slaughterer who does not know the laws of shechitah — it is forbidden to eat from his shechitah. These are: shehiyah, drasah, chaladah, hagramah, and ikkur.`,
  '2#main': `Shehiyah — how so? (Rambam, chapter 3 of Hilchot Shechitah, law 2) Behold, he began to slaughter and raised his hand before finishing the shechitah — and paused, whether unintentionally, whether intentionally, whether under duress, whether willingly — whether he or another came and finished the shechitah (if he paused the time it takes to lift the animal, lay it down, and slaughter). The measure of shehiyah in fowl and a small animal: the time it takes to lift a small animal, lay it down, and slaughter (until) the majority of the simanim, which is the valid shechitah measure — his shechitah is invalid (see seif kaf gimmel). If it was a small animal, the measure of shehiyah was the time to lift a small animal, lay it down, and slaughter; and if it was large, the time to lift a large animal, lay it down, and slaughter; and in fowl, the time to lift a small animal, lay it down, and slaughter. And some say that the measure of shehiyah in fowl is the time to slaughter the majority of one siman in fowl without lifting and laying down. According to their words one must be careful when he began to slaughter fowl and cut a little until the blood comes out and raised his knife from the neck, lest he finish the shechitah — for there is concern perhaps he slaughtered something of the esophagus; and even if he only raised his knife slightly there is concern, because fowl shehiyah is very brief. And even if the slaughterer says, "It is clear to me that I only cut the skin" — we do not rely on him, since blood came out. And if he comes to ask after he raised his knife — how should he act? They tell him to slaughter the trachea alone in another place, and afterward invert the esophagus and check it. And regarding practical application, one should be stringent in this reasoning except if it is a time of distress or great loss — then one may rely on the first reasoning. {Rama: And the settled custom in these lands is to declare treifah any shehiyah, even any amount, whether in fowl or in animal (Mordechai and Mahari Weil in laws of shechitah); and one should not deviate. And if after shechitah there is found in it gomi or the like lying in the esophagus or trachea and it was slaughtered together with it — treifah; for certainly he had to pause somewhat when cutting that thing after he slaughtered the siman, and it becomes shehiyah in any amount, and it is treifah (Terumat HaDeshen, siman 185).}`,
  '3#main': `He slaughtered a little and paused a little and returned and slaughtered a little and paused a little — if when all the pauses are combined there is the measure of shehiyah, his shechitah is invalid (and according to the custom in every case, treifah).`,
  '4#main': `One who slaughters an animal with a knife that is not sharp and was delayed the measure of shehiyah in the last minority of the first siman — behold, this is invalid.`,
  '5#main': `After he slaughtered the majority of one in fowl or the majority of two in an animal — shehiyah does not invalidate. According to this, there is no shehiyah in the trachea in fowl at all. And there is one who says that anything until the shechitah of both simanim is finished — shehiyah invalidates; and l'chatchila one should be careful to heed his words. {Rama: And even b'dieved the custom is to declare treifah; and therefore if after he slaughtered the majority of two the animal or fowl pauses to die — strike it on its head to kill it and do not return and slaughter (Terumat HaDeshen, according to Rashi and Semak and Mahari Weil and Or Zarua).}`,
  '6#main': `He slaughtered fowl and paused in it and does not know whether the esophagus was perforated — he returns and slaughters the trachea alone in another place and leaves it until it dies, and inverts the esophagus and checks it from inside; if no drop of blood is found in it, it is known that it was not perforated and it is kosher. {Rama: And the custom is to declare treifah everything, even if he only paused in the first minority of the trachea (Mahari Weil and Mordechai). And it is forbidden to sell it to a gentile as such; rather kill it and afterward sell it to a gentile (Hagahot Semak and Mordechai), because we are not expert in examining the esophagus and we are concerned for perforation of the esophagus (Agur). And for this reason, if one plucked the feathers from the fowl and blood came out, or cut the skin in an animal and blood came out from it — one should declare treifah, for we are concerned for perforation of the esophagus (Mahari Weil and Maharam of Padua, siman 63, and so in latter shechitah books). But if no blood came out and he did not cut all the skin — one may declare it kosher by slaughtering above or below and checking opposite the cut (Beit Yosef, not like Mahari Weil, shoresh 34). And therefore one should be careful not to pluck the feathers if he can slaughter without this (Or Zarua).}`,
});

// --- siftei-kohen (21) ---
patchFile('siman_023/siftei-kohen/part-001.txt', 'siftei-kohen', {
  '1#_': `<b>Any slaughterer who does not know, etc.</b> See above siman 1, seif 2, what he must know.`,
  '2#א': `[<b>And he raised his hand, etc.</b> The same applies if he did not raise [his hand] and only paused — he mentioned it as the ordinary way of speaking, and it is simple.]`,
  '2#ב': `[<b>And slaughter until the majority, etc.</b> It appears to me that for this reason the Beit Yosef added the word "until," because Rambam wrote (chapter 3 of Hilchot Shechitah, law 4): if he paused the time to lift it, lay it down, and the time to slaughter a minority of simanim — not the time to complete shechitah — this is doubt of neveilah; and Beit Yosef explained, and so it appears, that this means he paused the time of shechitah by a hair's breadth more than he would have paused the measure of shechitah; and therefore, since the matter is estimated by judgment, it is possible he will think he only paused the time to slaughter a minority of simanim, and perhaps he paused the time to slaughter the majority of simanim — end of his words; therefore the Beit Yosef emended the word "until," meaning he paused the time of shechitah until he reached the majority of simanim by a hair's breadth — the majority (and after it the Taz continues). And even though in such a case it is doubt of neveilah, the Beit Yosef was not precise about this, and so in several places. However, from Tosafot there (s.v. im yesh bah), and Hagahot Ashiri in the name of R' Yechiel and Mordechai and Agudah there, it appears clearly that we say "the piece becomes neveilah" in such a case; and so too is the view of R' Yerucham there; and it appears from these poskim that even in salting we say "the piece becomes neveilah" — see there: the Mechaber and Beit Yosef and other poskim were not precise about this.]`,
  '2#ג': `[<b>Until the blood comes out, etc.</b> Thus wrote Beit Yosef; and Mahari Weil, shoresh 34, wrote that even though it was cut, he does not forbid until blood comes out, and he was precise about this from that which it says "until the blood comes out"; and it does not appear to me that even if blood did not come out we are concerned perhaps he touched the esophagus; and that which it says "until the blood comes out" — he mentioned it as the ordinary way of speaking; however, where the slaughterer says "It is clear to me that I only cut the skin" — we do not rely on him, namely when blood came out, as the wording implies "we do not rely on him since blood came out" — end of his words. But Maharshal, chapter HaShochet, siman 14, wrote: and even though Beit Yosef questioned Mahari Weil, nevertheless I say he wrote well, etc.; and the Rav's view in Darkei Moshe and in Hagahot at the end of the siman is like Beit Yosef, as will be explained there; and so the latter authorities in their shechitah books.]`,
  '2#ד': `[<b>And even if he said "It is clear to me," etc.</b> See seif kaf 15.]`,
  '2#ה': `[<b>And afterward invert the esophagus and check, etc.</b> And for us, who are not expert in examination as below siman 33, seif 8 — treifah; and so too Beit Yosef at the end of the siman; and so in latter shechitah books; and Maharshal there wrote that in great loss or for the need of a mitzvah one should look to be lenient and rely on the latter great ones who practiced and ruled practical halakhah for permission, as is found in Hagahot in part of Semak and Mahari Weil copied it in responsum siman 34, etc. — see there.]`,
  '2#ו': `[<b>And the settled custom, etc.</b> It is simple that this refers after he relied on it, that even in great loss and the like the custom is to declare treifah; and so it appears in Darkei Moshe and other latter authorities; and so Bach wrote explicitly; and so is practiced — not like the Taz.]`,
  '2#ז': `[<b>And if after shechitah gomi is found, etc.</b> In Terumat HaDeshen he compared this law to seif 4, that when he paused on something that has no aspect of shechitah — it is shehiyah; and all the more so here. And afterward he wrote: and you may ask — who tells us that he paused when cutting the gomi? Perhaps he actually cut the esophagus and the gomi at once, equal in time, and if so the knife did not cease even a moment from the siman. It appears that he must say thus: for behold the siman is stretched at the time of shechitah, and the gomi is not stretched because it is not attached to the jaw and body; and it is known that any soft thing the knife's edge strikes — if it is stretched it is cut faster than if it were not stretched; and therefore, since the gomi too is soft and not stretched, the knife's edge paused longer to cut it than when cutting the siman; and it turns out he did not cut them exactly equal — end of his words; and Darkei Moshe and Maharshal, chapter HaShochet, siman 10, and Mahari Weil bring it. And I did not know why Bach was lenient to permit long thin grass lying along the esophagus without reason and proof; and also from Beit Yosef's words, who wrote "gomi or the like," it implies as I said; and so it appears in the Taz — see there.]`,
  '3#_': `<b>His shechitah is invalid.</b> Meaning: doubt of neveilah that requires examination and was not clarified.`,
  '4#_': `<b>This is invalid.</b> Here too — doubt of neveilah that requires examination in the Gemara: he paused in a minority of simanim — what is the law? Teiku; and we stand stringently. The reason: since the majority of the siman was cut, it is as if the whole was cut; and what he does holacha u'va in the remaining minority is as if he does holacha u'va with its hand or foot; and therefore when he was delayed the measure of shehiyah in the last minority of the first siman — treifah in an animal; not so in fowl, whose fitness is in one majority. So too the poskim. And since the Rav did not emend here either "according to the custom in every case treifah" even if he was not delayed the measure of shehiyah — it implies he holds that here specifically we require the measure of shehiyah even for us; and so it appears in the Taz; and this is because he is occupied here with shechitah of the simanim. And see siman 18, seif kaf 11, what is written on this.`,
  '5#א': `[<b>According to this there is no shehiyah in the trachea in fowl at all.</b> For in the first minority of the trachea shehiyah does not apply, as above — like half a defective trachea is only doubt; not so in the esophagus, where shehiyah applies in the first minority of its perforation in any amount, as below siman 33; but the trachea is cut off in its majority, as below at the beginning of siman 34.]`,
  '5#ב': `[<b>Strike it on its head, etc.</b> And in Sefer HaTerumot he concludes: provided he does not break its neck-bone; and Maharshal wrote on this: it is excessive stringency, for it is obvious if he breaks the neck-bone with a knife it does not appear like shechitah — why should we be so stringent? — end of his words. Understand: it is forbidden because of shehiyah; and it is not so. Rather, the reason is as we learn in chapter 25: one who breaks the neck-bone of an animal before its soul departs — forbidden because of absorbing blood in the limbs; and it will be explained below siman 67 that l'chatchila it is forbidden to break the neck-bone even to eat it raw, as Beit Yosef wrote there in the name of Shibbolei HaLeket; and Maharshal himself ruled in chapter 25, siman 99; and so the Taz explained — see there.]`,
  '5#ג': `[<b>And he should not return and slaughter.</b> R' Tzvi wrote in Shechitot that it is permitted to slaughter afterward with a flawed knife, and it is not clear; and so it appears from Semak's wording, who wrote "he should not return and slaughter with a knife or a sickle," because he paused and an unspecified sickle is flawed; and moreover in any case it is forbidden because of ikkur in the last minority. So too Bach in siman 24, seif 12, in laws of ikkur; and he wrote: if he slaughtered with a flawed knife, even after he already slaughtered the majority with a valid knife — forbidden; and see siman 2, seif kaf 29, on laws of shehiyah in the last minority.]`,
  '6#א': `[<b>He slaughtered fowl, etc.</b> It implies specifically in fowl, whose fitness is in one siman — this remedy applies to it; but not in an animal; and so is simple among the poskim.]`,
  '6#ב': `[<b>And he does not know, etc.</b> It implies: if he knows clearly that the esophagus was not perforated — his shechitah is valid even without examination, such as where he grasped the trachea alone in his hand, as Beit Yosef wrote in this siman and in seif 21, and Beit Yosef there; and see there and siman 34 on what is written in seif 1, that even if the slaughterer says "It is clear to me that I only cut the skin" — we do not rely on him: there, since he did not intend from the outset for this, it is a matter that does not depend on a person and was not in his mind — similar to above siman 18, seif 14, that where he knew there is masuchseches he is believed to say "It is clear to me I only did holacha"; and when he did not know before shechitah he is not believed, because a matter that does not depend on a person was not in his mind — see there.]`,
  '6#ג': `[<b>In another place, etc.</b> The reason: because there is concern — perhaps since he already began to slaughter in that place it will be easier to strike the esophagus, and he will come to say "now it was slaughtered" and "before I did not touch it"; and perhaps before he touched it, and he validates the prohibition improperly. And it deals with one who slaughtered the trachea alone; or perhaps before he did not touch it, and now since he is likely to strike it he will strike it — it turns out he invalidates improperly. Good advice the Mechaber teaches — end of Beit Yosef and Perishah.]`,
  '6#ד': `[<b>Even if he did not pause, etc.</b> And Rokeach, siman 381, wrote: he slaughtered the esophagus and left it and slaughtered the windpipe and afterward slaughtered and finished the esophagus — since he is occupied in shechitah, it is valid — end of his words. And in my humble opinion, the same applies for us where he did not pause at all before he began to slaughter the windpipe; and so in Shechitot of R' Tzvi; and Zivchei Riv challenged him not according to law.]`,
  '6#ה': `[<b>And it is forbidden to sell it to a gentile, etc.</b> One should not challenge: for Beit Yosef wrote in seif 27 of treifot that are unknown, and some validate that treifah — even though we rule to forbid it, nevertheless it is permitted to sell it to a gentile because of safek safeka; and here too, even though we rule to declare treifah, nevertheless since it is only a concern that perhaps he will sell it — this is safek safeka: perhaps the esophagus was not perforated; and if we were expert in examination we would see it was not perforated; and if you say it was perforated — perhaps the gentile will not sell it to a Jew. These are two "perhaps"s here. They decreed on a Torah doubt, or even on something whose prohibition is only rabbinic from the root, such as bread of an Israelite that a gentile baked (below siman 112, seif 11) — the decree not to sell lest he sell it to an Israelite; but regarding something in which there is a dispute of amoraim or rabbis, we always say regarding selling to a gentile that it is rabbinic — follow the lenient side; for a doubt in a dispute is not like a doubt in the act itself — and it is simple. And it requires study in many places in the Gemara on this matter — end of Maharai in Terumat HaDeshen, seif 178. And in my humble opinion, in any case there is no difficulty: for here, since the doubt is because of our lack of knowledge — we are not expert in examination — it is not called a doubt at all, as the poskim wrote in several places; and as written in siman 53, seif kaf 14, and siman 98, seif kaf 9; and so Maharai himself in Hagahot Sha'arei Dura, siman 87, regarding a broken bone — see there; and even safek safeka does not help in such a case, as written in siman 55, seif kaf 4.]`,
  '6#ו': `[<b>Rather kill it and afterward sell it, etc.</b> And Mordechai wrote in the name of Rif: it is forbidden to leave it in his house, lest a mishap come — therefore; and Darkei Moshe brings it. But if he need not leave it, only one day until it becomes pregnant and gives birth — a treifah does not give birth — it is permitted, as below siman 57, seif 18, and siman 86, seif 9.]`,
  '6#ז': `[<b>If he plucked the feathers, etc.</b> In Darkei Moshe he wrote in the name of Maharam of Padua the reason in this: for even though we know that through plucking feathers the esophagus is not perforated, nevertheless we decree lest the skin tear from the neck; and he wrote: according to this there is no distinction between plucking feathers at the time of shechitah or before — always, if blood came out from them, one should declare it treifah because of the decree; and it is great stringency in my eyes — end of his words. Also Maharshal, chapter HaShochet, siman 14, validated this and wrote it is stringency without reason; and so Chayei Adam in the name of Rashba that Beit Yosef brought, and latter authorities, that there is no concern here for perforation of the esophagus; and therefore it appears as Bach wrote, that in great loss and the like one should be lenient.]`,
  '6#ח': `[<b>But if no blood came out, etc.</b> Behold: if blood came out, even though he did not cut all the skin; or he cut all the skin even though no blood came out — treifah. And that which it says at the beginning "or he cut the skin and blood came out" — this means part of the skin; and so Darkei Moshe wrote explicitly. But Maharshal there validated both where he cut part of the skin and blood came out, and where he cut it all and no blood came out; and he only declares treifah where he cut it all and blood came out. And in what he permits where he cut it all and no blood came out — I already wrote in seif kaf 4 that we do not rule thus. But in what he validates where he cut part of it even if blood came out — it appears so at first glance: for what concern is there, since he did not cut all the skin? And so the Taz brought two views on this; therefore it appears one should be lenient in great loss and the like; but in any case one should not be lenient, lest it be only plucking of a feather that they practice to declare treifah when blood comes out; and so Bach declares treifah when part of the skin was cut and blood came out. However, all this is when the slaughterer did not say "It is clear to me I did not touch the esophagus"; but when he says "It is clear to me," even if he cut all the skin it is valid when no blood came out, as implied by the poskim and the Mechaber in seif 1; and as written in seif kaf 4; and where he intended from the outset not to touch the esophagus, such as where he grasped the trachea alone in his hand — even if he cut all the skin and blood also came out, it is valid; and as written in seif kaf 15 — examine this.]`,
});

// --- turei-zahav (8) ---
patchFile('siman_023/turei-zahav/part-001.txt', 'turei-zahav', {
  '2#א': `<b>In order to lift a large animal and lay it down.</b> This is Rambam's view; and in Tur it is written so too in the name of Rif and Ra'osh. The author of HaDrishah already wondered — a settled wonder — for in Ashiri it is explained that it is not so; rather we estimate lifting and laying down: small for small and large for large; only for shechitah we estimate even small according to large. And he answered with difficulty: Tur means we estimate in slaughtering large and its lifting and laying down of itself; and the wording does not imply this, for "its lifting" refers to what he mentioned first. And in my humble opinion there is a textual error here, and it should read: "rather, that he wrote: even though we estimate the time of shechitah of an animal and its lifting," etc.; and our Rabbi's intent: Ra'osh agreed with Rif in this, that for shechitah we estimate even from large to fowl — not as he mentioned before; rather for lifting and laying down he disagrees; and therefore he said "rather he wrote: even though we estimate the time of shechitah of an animal and laying down," each according to its law; nevertheless this is specifically for animal, but for fowl there is no measure of laying down at all.`,
  '2#ב': `<b>To declare treifah any shehiyah.</b> Nevertheless this includes only if he raised the knife even somewhat, since he removed it from the neck — one does not distinguish whether he paused a lot or a little; but if he did not raise at all, only the knife was pushed from place to place — it is valid even for us, as we find regarding one who slaughters in two or three places in siman 21; and so I found in Maharshal; and he wrote: nevertheless it appears specifically where he ceased from slaughtering or raised the knife; but if his hand was pushed downward there is no shehiyah on him and it is valid. And what should we be concerned for? Even if the esophagus was perforated — it is one shechitah — end of his words.`,
  '4#_': `<b>One who slaughters an animal, etc.</b> Specifically in an animal: since two simanim require shechitah, and if he delayed while slaughtering the last minority of the first siman — even though he did holacha u'va in the way of shechitah, it is invalid; since he slaughtered the majority of the siman, the remaining minority is considered as slaughtered; and what was delayed in his slaughter is not counted as part of the shechitah, and it is as cutting with its hand or foot. Not so in fowl, whose fitness is in one siman. And see what I wrote on this at the beginning of siman 21.`,
  '5#א': `<b>There is no shehiyah in the trachea.</b> For no matter how much he has not yet slaughtered the majority, he can afterward return and slaughter — like half a defective trachea: one cuts whatever amount and permits it.`,
  '5#ב': `<b>Strike it on its head.</b> See what is written on this in siman 67.`,
  '6#א': `<b>And he slaughters the trachea alone in another place.</b> That he needs another place — Beit Yosef explained: perhaps since he already began to slaughter there it will be easier to strike the esophagus, and he will come to say "now it was slaughtered" and "before I did not touch it"; and perhaps before he touched it, and he validates the prohibition improperly. Nekudat HaKesef: and he was not precise — for certainly any drop of blood found he will not attribute to leniency and forbid from doubt; for we rule: any drop of blood found inside is forbidden everywhere it is; if so, there is no stumbling block here. And it appears to me the reason: when he wishes to grasp the trachea alone he must grasp it forcefully; and if he does so in the place he already cut, there is concern that thereby it will detach and the cut widen until it is invalid — therefore he grasps it in a place that is whole. And further it appears to me: if he slaughters in the first place, there is concern he will ruin it for himself — perhaps he already slaughtered the majority in the trachea, and then there is no invalidation in what perforated the esophagus; and it is impossible to see well at the time of shechitah whether the majority was slaughtered, since it is soiled with blood — therefore he slaughters in another place, and afterward he can see in the first place that if the majority was slaughtered, perforation of the esophagus will not harm him.`,
  '6#ב': `<b>And we are concerned for perforation of the esophagus.</b> This is a thing impossible to say — that through plucking a feather the esophagus would be perforated. And in the version of the Hagahah that Maharam of Padua brought, siman 83, the reason is written: one who sees would think to permit also a bar goose that blood spurts, as stated in siman 33. And it is possible that Rama too here, who wrote the reason because of perforation of the esophagus, wrote regarding the second division "he cut the skin," etc.; but in the first division the reason is because of a decree, as I explained; and since the main reason is because of a decree, it is difficult to add a decree that was not mentioned in the Talmud; nevertheless, since it is practiced stringently, it is practiced — only one should not be stringent except if a few drops of blood came out in a matter that resembles spurting blood; but if they did not come out, only redness is seen — one should not be stringent at all. And I proposed this matter before Maharam Yafeh, z"l, and he agreed with my words. I again saw in Maharshal, who wrote in the name of Chayei Adam in the name of Rashba in plucking a feather that Beit Yosef brought, that there is no concern for perforation of the esophagus; and he wrote on this: and not only that — it appears in my eyes that even with a knife that we are stringent and concerned for perforation of the esophagus, whether in fowl or in animal, it appears specifically where all the skin was cut; but if the skin of the animal was cut only in part of its thickness and not entirely — there is no concern; and even if blood came out there is no room for concern — end of his words. And this is unlike Rama's words here, who wrote "but if no blood came out and he did not cut all the skin" — implying if blood came out, even though he did not cut all the skin, it is forbidden. But it appears the main point is like Rama's words: since blood came out we are concerned perhaps a very fine hole was perforated and touched the esophagus, and it is not visible to us, or the blood blocked it; for otherwise from where did this blood come, since in the skin there is no blood? Therefore one may not be lenient in a cut, even part of the skin, when blood is seen; and in plucking feathers, when blood is seen one should be stringent specifically if a little blood came out, as we mentioned above.`,
  '6#ג': `<b>And he did not cut all the skin.</b> This refers to animal specifically; but in fowl it is not relevant to say so; and so explicitly in responsum of Mahari Weil there. But nevertheless it appears simple: if on the fowl's skin there is some dry scratch on its outer side, and he slaughtered elsewhere and saw on the inner side that there is no defect on the skin — one should not be stringent in this according to all views.`,
});

// --- beer-hagolah (12) ---
patchFile('siman_023/beer-hagolah/part-001.txt', 'beer-hagolah', {
  '1#_': `Statement of Rav Yehudah, who said Shmuel — Chullin, daf 9.`,
  '2#א': `Mishnah there, daf 32.`,
  '2#ב': `Ra'osh and Shas.`,
  '2#ג': `Like R' Yosi bar Chanina there, and as Ran explains according to Rif — R' Yosi does not disagree with R' Yochanan and Shmuel; and so Rambam, chapter 3 of Hilchot Shechitah.`,
  '2#ד': `Rashi there, and Rav, and he wrote that R' Yosi bar Chanina is certain in Rav's method; and so Semag; and so it was explained in Hagahot — practical halakhah; and so Semak and Mordechai (and Agudah and Kol Bo).`,
  '2#ה': `There in Mordechai (and Agudah and Kol Bo in the name of Rif and Hagahot Ashiri).`,
  '2#ו': `Beit Yosef.`,
  '3#_': `Rava's question, and it was not resolved — stringently there, daf 32.`,
  '4#_': `R' Huna bar Natan's question, and it was not resolved there; and as R' Oshaya explained, whom Tosafot brought, daf 30; and so the agreement of the poskim.`,
  '5#א': `Rambam there, from Tosafot (and Or Zarua).`,
  '5#ב': `Tur in the name of Rashi in explaining R' Huna's question (and Or Zarua).`,
  '6#_': `Rambam's wording there, from that which Rav Yosef, son of Rava, in Chullin, daf 28.`,
});

// --- baer-heitev (15) ---
patchFile('siman_023/baer-heitev/part-001.txt', 'baer-heitev', {
  '2#א': `<b>Willingly.</b> And Shach wrote: that which the Mechaber wrote "and he raised his hand" is not precise; rather the same applies if he did not raise and only paused — he mentioned it as the ordinary way of speaking.`,
  '2#ב': `<b>Comes out.</b> And Shach wrote: the same applies when no blood comes out — he mentioned it as the ordinary way of speaking; however, if the slaughterer says "It is clear to me that I only cut the skin" — we do not rely on him, namely where blood came out, as the wording implies "we do not rely on him since blood came out." And Maharshal ruled that it is forbidden only specifically when blood came out.`,
  '2#ג': `<b>It.</b> And Shach wrote in the name of Maharshal: for us, who are not expert, one should declare treifah unless in great loss.`,
  '2#ד': `<b>Any amount.</b> And Shach wrote: and even in great loss. And Taz wrote: nevertheless this includes only if he raises the knife even somewhat, since he removed it from the neck — one does not distinguish whether he paused a lot or a little; but if he did not raise at all, only the knife was pushed from place to place — it is valid even for us, as we find regarding one who slaughters in two or three places above in siman 21; and so Maharshal; and he wrote: what should we be concerned for? Even if the esophagus was perforated — it is one shechitah — end of his words.`,
  '2#ה': `<b>Treifah.</b> And Shach wrote: and I did not know why Bach was lenient to permit long thin grass lying along the esophagus without reason and proof. He wrote: an incident came to him where one slaughtered fowl and at the time of shechitah cut his finger and declared treifah because he panicked from the cut on his finger and raised the knife somewhat — and it is shehiyah; and several geonim agreed with him that it is treifah. And in responsum of Or Zarua, siman 86, he distinguishes: if he cut his finger not at the time of cutting the siman, such as after he passed the entire knife in holacha or hava'ah outside the neck, and then cut his finger, and afterward returned and did holacha or hava'ah with the knife and finished the shechitah — certainly it is shehiyah and invalid. But if he cut the simanim and his finger at once — there is no shehiyah here, and it is not comparable to gomi found within the simanim, for there the gomi is soft and through the knife's sharpness he pauses longer to cut it than when cutting the siman. And regarding kashering utensils or transferring the slaughterer — lean to leniency. And if the slaughterer is in doubt in what manner the cut on his finger was — be lenient — see there. And if he cut the finger of the one holding the simanim — it is kosher, for the slaughterer is not startled. See responsum Chinuch, Beit Yosef, question 24 — end. And I say: not only gomi, but even a hair found either in the esophagus or trachea is forbidden — see there. He wrote to Kenesset HaGedolah: if the esophagus is full of bran feed and our eyes see the knife full of bran and going down with spurting of blood — forbid by law — see there. If in doubt whether the gomi was cut with the shechitah or not — do not declare treifah, since it is mere stringency that they practice to forbid shehiyah in any amount; one may be stringent in certain cutting but not in doubt. And so I ruled practical halakhah several times — Kenesset HaGedolah, this siman.`,
  '3#_': `<b>Invalid.</b> Shach explains: it becomes doubt of neveilah.`,
  '4#_': `<b>Invalid.</b> And Shach wrote: and specifically in an animal, since one must cut both simanim in an animal; if so, when he slaughtered the majority of a siman as one, what he does holacha u'va in the last minority of the first is as if he does so with foot or hand — and it is shehiyah. Not so in fowl: when the majority of one siman is slaughtered it is immediately kosher. And since Rama did not write here "according to the custom declare treifah in every case," it implies he holds that here specifically we require the measure of shehiyah even for us; and the reason: since he is occupied here with shechitah of the simanim. However, certainly l'chatchila even in fowl one should not slaughter with it, since two simanim are required in fowl l'chatchila too — Mahari Weil.`,
  '5#א': `<b>To kill it.</b> And Shach wrote in the name of Sefer HaTerumot: only provided he does not break its neck-bone; and see siman 67 that it is forbidden to break the neck-bone even to eat it raw; and see siman 67 in Hagahah, seif 3, what must be asked on this and what Shach and Taz resolve there. See in Beit Yosef, siman 138: fowl called indik (and in another language "English hen") — most of the world prepares its head with an axe when it convulses; one should rebuke them not to do so until after blood comes out; and the same for other animals as long as blood spurts; and b'dieved it is permitted to eat its flesh through cutting and salting — Darkei Shalom, siman 37.`,
  '5#ב': `<b>And slaughter.</b> And Shach wrote: even not with a flawed knife, because of ikkur in the last minority.`,
  '6#א': `<b>And it is kosher.</b> And Shach wrote: it implies if he knows clearly that it was not perforated, such as where he grasped the trachea alone in his hand — valid even without examination; and it is not comparable to seif 1, that if the slaughterer says "It is clear to me I only cut the skin" we do not rely on him: there he did not intend from the outset, and it is a matter not dependent on a person; not so here, if he intended to grasp the trachea alone — valid even without examination.`,
  '6#ב': `<b>Of the trachea.</b> And Shach wrote that one should permit even for us where he slaughtered the esophagus and left it and slaughtered the windpipe and afterward slaughtered and finished the esophagus, if he did not pause at all before he began to slaughter the windpipe, since he is occupied in shechitah — valid; and so in Sefer Ohel Mo'ed in the name of Razah: an animal that has a pit in its esophagus — he slaughtered and struck the pit, raises the knife and slaughters immediately before pausing above or below the pit; and so Peri Chadash; and see Shach. And in Zivchei Riv he challenged this not according to law — end of his words.`,
  '6#ג': `<b>As such.</b> And Shach wrote: one should not challenge — for we rule in siman 57 regarding treifah that is unknown, and some validate that treifah, that nevertheless it is permitted to sell to a gentile because of safek safeka; and here too, even though we rule to declare treifah, nevertheless since it is only concern that perhaps he will sell it — safek safeka: perhaps if we were expert in examination we would see it was not perforated; and if you say it was perforated — perhaps the gentile will not sell to an Israelite. Maharai answered: a doubt in a dispute is not like a doubt in the act itself; and it requires study in many places in the Gemara on this. And Shach answered: in any case there is no difficulty: since the doubt is because of our lack of knowledge — we are not expert in examination — it is not called a doubt at all, as the poskim wrote in several places. And he wrote in Hagahot: and that which it says "kill it," etc. — I say: rather before death sell it to a gentile, and afterward the gentile kills it before us; for it is forbidden to cause treifot in something permitted by Torah to eat. And Peri Chadash in kaf alef disagrees with him.`,
  '6#ד': `<b>Esophagus.</b> And Shach wrote in the name of Mordechai: it is forbidden to leave it in his house lest mishap come; but if he need not leave it, only one day until it becomes pregnant and gives birth — a treifah does not give birth — it is permitted, as below siman 57, seif 18, and siman 86, seif 9.`,
  '6#ה': `<b>Esophagus.</b> And Shach wrote in the name of Darkei Moshe: even though we know that through plucking feathers the esophagus is not perforated, nevertheless we decree lest the skin tear from the neck; according to this there is no distinction between plucking at the time of shechitah or before — always, if blood came out from them, declare treifah because of the decree; and it is great stringency in my eyes. Also Maharshal validated this and wrote it is stringency without reason; therefore it appears as Bach wrote, that in great loss one should be lenient. And Taz wrote the reason for this stringency: lest one come to permit also a bar goose whose blood spurts, as in siman 33; therefore one forbids only specifically when blood came out, for since blood came out we are concerned perhaps a very fine hole was perforated and touched the esophagus, and it is not visible to us, or the blood blocked it; for otherwise from where did this blood come, since in the skin there is no blood (and I omitted the sugya in Yoma, daf 48, that there is blood in the skin — responsum Shai, question 28). Therefore one may not be lenient in a cut, even part of the skin, when blood is seen; and in plucking feathers, when blood is seen one should be stringent specifically if a little blood came out — end. But if only redness is seen, not blood — do not be stringent at all. And he wrote he proposed this before Maharam Yafeh and he agreed with his words.`,
  '6#ו': `<b>The cut.</b> And Taz wrote: it appears simple — if on the fowl's skin there is dry scratch on its outer side, and he slaughtered elsewhere and saw on the inner side that there is no defect on the skin — do not be stringent according to all views. And if the upper membrane on the simanim peeled even somewhat — treifah; and examination does not help, since we are not expert in examining the esophagus. However, in mere swelling around the simanim, when there is no other defect — we are not concerned for perforation of the esophagus; rather we attribute it to illness — see Kenesset HaGedolah.`,
});

// --- beur-hagra (12) ---
patchFile('siman_023/beur-hagra/part-001.txt', 'beur-hagra', {
  '2#א': `<b>And he paused, etc., and he or another came, etc.</b> See there in the Mishnah and Tosefta.`,
  '2#ב': `<b>(Likut) In order to lift, etc.</b> Like R' Yehoshua ben Chananya, and not like Rashi's version, who reads "there is between them" only regarding standing to lay eggs alone; and that is its explanation according to his version. But according to Rashi's version, R' Yosi and Shmuel disagree, and lifting and laying down are not required — and this is what "some say," etc., without lifting and laying down (and that which he mentions fowl is because on this the first view disagrees in two matters; and also because he meant "and according to their words," etc. But in Likut below he explains plainly like Shulchan Aruch, that the first view is only in fowl). And in Terumat HaDeshen he wrote one should be concerned for Rashi's words in both — end.`,
  '2#ג': `<b>Until the majority of simanim.</b> Which is the Torah measure of shechitah even l'chatchila [and not like Rambam that they brought in Terumat HaDeshen (who explains) from that which it asks "he paused in a minority of simanim — what is the law?" if he paused the measure of a minority of simanim; and so in Terumat HaDeshen they contradicted it, for it should read "like a minority"].`,
  '2#ד': `<b>And some say, etc.</b> For he holds R' Yehoshua ben Chananya holds like Rav, since he holds small for small, all the more fowl for fowl; and Hagahot and first reasoning hold R' Yehoshua ben Chananya does not deal with fowl at all, and holds like R' Yochanan. <br><b>(Likut) And some say the measure, etc.</b> This is Rashi's method, who ruled like Rav: measure fowl for fowl — R' Yehoshua ben Chananya is according to him, who says small for small, and if so the same fowl for fowl; and he also holds without lifting and laying down, even in large and small animal; and as the version of R' Peretz: standing to lay eggs — aleph bet; and he ruled like Shmuel and R' Yochanan in this, not like R' Yehoshua ben Chananya and R' Chanina; and so in Semag and Mordechai: we do not estimate at all in lifting and laying down, even for animal. But Ra'osh wrote: there is no such version reading aleph bet; and all agree with R' Yehoshua ben Chananya, only he wrote that R' Yehoshua ben Chananya, since he did not say "and fowl for fowl," implies that in fowl he does not require lifting and laying down — and this is what "some say," etc. But according to Rashi and Shas, even in animal we do not require, as above; and Ra'osh explained Rif's words, who ruled like R' Yochanan even in animal — meaning even large for fowl, and all the more large for small; only for lifting and laying down we estimate large for large and small for small; and in fowl, without lifting and laying down at all — Taz; and not like Be'er HaGolah, who forces an elephant into a basket of sin (i.e., distorts the sources); but R' Yehudah explains Rif's words like Rambam's words — and this is the first reasoning — end.`,
  '2#ה': `<b>(Likut) Perhaps he slaughtered something, etc.</b> For shehiyah invalidates in the first minority of the esophagus, as in the Tosefta that Tosafot brought there, letter 2, s.v. hachalid, etc.: it was taught "he slaughtered a minority of esophagus," etc.; and in the Gemara there, 30b, R' Hoshaya asked, etc. — end.`,
  '2#ו': `<b>And if he comes, etc.</b> As written above, 28a, that incident, etc.`,
  '2#ז': `<b>And the custom, etc.</b> Because it is impossible to be expert in the measures, they agreed to forbid in every case.`,
  '2#ח': `<b>And if found, etc.</b> For the simanim are stretched and slaughtered quickly, not so a thing lying in place; and even though he is occupied in shechitah it is called shehiyah, as written in seif daled — Terumat HaDeshen.`,
  '5#א': `<b>After, etc., and according to this, etc.</b> Tosefta: he slaughtered half the windpipe and paused the time of shechitah and afterward slaughtered all of it — his shechitah is valid; one or majority of one in fowl, even though for a long time — his shechitah is valid. And in the Gemara, 29a: "Do you think in an animal," etc.`,
  '5#ב': `<b>And therefore, etc.</b> Rashi there.`,
  '6#א': `<b>And the custom, etc.</b> Because it is impossible in examination, as written; and shehiyah invalidates in the first minority of the esophagus, which is in any amount, as in the Tosefta: he slaughtered a minority of the esophagus and paused the time of shechitah and afterward slaughtered both; or the esophagus was perforated and afterward he slaughtered both — treifah.`,
  '6#ב': `<b>And it is forbidden to sell it, etc.</b> As written in 53b; and see above siman 57, seif 18, and seif 20 in Hagahah. <br><b>(Likut) And it is forbidden to sell it, etc.</b> As written (53b) regarding doubt of drasah; and in chapter 5 of Avodah Zarah (65b) regarding wine that fell on wheat — Ran and Mordechai there — end.`,
});

// --- kereti (18) ---
patchFile('siman_023/kereti/part-001.txt', 'kereti', {
  '1#_': `He does not know — but from the plain majority it is specified regarding expert shechitah.`,
  '2#א': `And he raised — not precise; he only mentioned it as the ordinary way of speaking.`,
  '2#ב': `Until majority — Shach explains: even if he did not pause the time to slaughter the majority of simanim, only lacking any amount from the majority — nevertheless this was Rava's question according to Rambam's method, who slaughtered in a minority of simanim; and they explain "like a minority" with kaf — only that it was almost majority and now is minority; and it was resolved teiku; therefore this is doubt of neveilah; and the Mechaber should have mentioned it is doubt — good reasoning; only Shach was not so precise; and see Peleti, where I wrote another explanation.`,
  '2#ג': `Which is the valid shechitah measure — see Peleti: we follow the measure of one who slaughters with a fine knife; and even if he slaughtered with a bad knife and pauses in his slaughter — we do not follow his slaughter, only as one quick man with a fine knife in his hand.`,
  '2#ד': `Shechitah — and one may say stringently: the measure is one who slaughters two simanim, trachea and esophagus, as one, and not one after the other, for more time is needed; therefore I brought in Peleti: be stringent only if there is time to slaughter the esophagus and a bit of trachea — half a defective trachea; in such a manner the shechitah is valid, and the time for shechitah is shehiyah — see there.`,
  '2#ה': `And in fowl — see Peleti what I wrote on this to resolve Beit Yosef's difficulty on Ra'osh — see there.`,
  '2#ו': `Until blood comes out — certainly even if no blood, we are concerned perhaps he touched the esophagus; only when he says "It is clear to me I did not touch the esophagus" — here there is a difference: if blood comes out, behold defect is before us; not so when no blood — no defect; he is believed saying "It is clear I did not touch" — so Shach and latter authorities. And Peri Chadash wrote: all this is if the skin was cut; but if the skin was not cut through and through, even if blood came out — kosher, for it is skin blood; he did not cut through and through.`,
  '2#ז': `Comes out — and behold Ran's view, and so Rashba: the measure of shechitah is time to cut the skin and simanim, but not feathers. But in Peleti I wrote it does not appear so from Rambam's words and Terumat HaDeshen — see there; and one should be stringent.`,
  '2#ח': `In another place — and according to one who says in a known place the esophagus has examination from outside, even in animal one slaughters in another place — see below siman 34.`,
  '2#ט': `And afterward, etc. — and for us, who are not expert in examination, that fowl has no remedy; see Shach, Maharshal — his view is to be lenient in great loss; and do not be lenient lightly.`,
  '2#י': `Any shehiyah — but if pushed in his hand at the time of shechitah from place to place, it is not called shehiyah — Taz.`,
  '2#כ': `Gomi — and the same for long grass: it is impossible that the siman and gomi be cut at one time equally; and the incident contradicts it; and he will not escape that he paused somewhat — Shach and Peri Chadash.`,
  '3#_': `Invalid — it should read it was not resolved; and doubt of neveilah.`,
  '4#_': `Animal specifically — in animal; but in fowl, since he slaughtered one siman the shechitah is already finished and shehiyah no longer applies; but in animal, since he slaughtered the majority of a siman, behold it is as slaughtered; and what he still slaughters in that siman is cutting flesh — and behold this is interruption for the second siman.`,
  '5#א': `And there is one who says — this is Rashi's view, who holds certainly after the majority was slaughtered he is not obligated to slaughter more; but if he slaughtered, it is one shechitah and all four laws invalidate it. See Peleti, where I brought this view — Torah invalidation, not rabbinic.`,
  '5#ב': `Strike on its head — see below siman 74.`,
  '6#א': `And forbidden to sell it — see below siman 57; and here it is doubt in shechitah and presumption of prohibition applies — be more stringent.`,
  '6#ב': `And we are concerned for perforation — it is stringency without reason; therefore in place of loss one may permit.`,
});

// --- peleti (4) ---
patchFile('siman_023/peleti/part-001.txt', 'peleti', {
  '2#א': `If he paused, etc. — this entire law is Rambam's wording in chapter 3 of Hilchot Shechitah, and its source is the Gemara: Rav holds measure of animal shechitah for animal and fowl for fowl; Shmuel and R' Yochanan say even animal for fowl. In the West, because of R' Yehoshua ben Chananya: in order to lift, lay down, and slaughter — small for small and large for large. And Rashi, according to Rif and Rambam: R' Yehoshua ben Chananya spoke only of small animal for small; but in fowl he agrees they were lenient to estimate small-animal shechitah; but for small animal they did not permit estimating more than small for small. And since R' Yehoshua ben Chananya did not mention fowl, it implies there are only these two measures — small and large — and fowl is included in them. And these are Rambam's words above; and Ra'osh wondered and wrote that according to his words we are lenient to estimate in laying down animal for fowl — why not estimate laying large for fowl? And further, he wrote we estimate from small to small, not large to small — if so, why are we lenient in fowl to estimate animal for small? And Kessef Mishneh wrote: what Ra'osh questioned here — to be lenient in laying animal for fowl, why not estimate large for fowl — are wondrous words; for this matter does not depend on us to be lenient or stringent, for it is among the measures given to Moses at Sinai; and what he questioned — why they were lenient in fowl more than animal — one may say: so they learned from Sinai, as Rashba wrote — end. And in truth, at first glance Ra'osh's words are wondrous: what leniency and stringency is here? Do we be lenient in prohibitions and doubt of neveilot? And it is obvious it is halakhah leMoshe miSinai; and what is there to question from one to the other? Therefore it appears to me this is Ra'osh's intent: that which we rule in fowl "measure of animal shechitah" — we learn from R' Yehoshua ben Chananya, who said large and small and omitted fowl, implying he holds fowl is included in those measures, etc. And on this Ra'osh rightly challenged R' Yehoshua ben Chananya: if you came to learn this measure to be lenient in fowl to estimate animal laying, you should also be lenient large for fowl; and why are we lenient in fowl from animal and not fowl from fowl? And we need not say thus was halakhah to R' Yehoshua ben Chananya. One cannot say so: for he holds in Nazir, daf 29: a man may vow his son a nazir to train him in mitzvah; and that which he slaughters — he holds there is no Torah shechitah for fowl; if so, all five laws are not from Torah in fowl, only rabbis forbade because of the taste of animal; if so, this extended shehiyah more than in animal is not a law at all, only rabbis saw to be stringent and lenient here — and he properly challenges: if so, according to R' Yehoshua ben Chananya it is only rabbinic decree — why did Chazal see to be stringent and lenient, like Ra'osh's difficulty? And thus it is not R' Yehoshua ben Chananya's intent at all; and R' Yosi does not deal with fowl at all — and it is settled. And this is the measure of Ra'osh's words — clear and precise.`,
  '2#ב': `Until majority, etc. — in Kereti I wrote Shach's explanation in Rambam: he wrote if he paused the time to slaughter a minority of simanim, not the time to complete shechitah — doubt of neveilah — end; and commentators wrote thus Rambam explains Rava's question "he paused in minority of simanim," and it is possible the version read "like minority of simanim" with kaf. And their explanation is as I wrote in Kereti; and this is great difficulty perforce — how much is lacking from majority, much or little — ultimate narrowing. Therefore it appears to say: the halakhah leMoshe miSinai was: if he paused the time in which one could perform effective shechitah — it is shehiyah; if so, simply we say: time to slaughter trachea and esophagus each. And see Kereti, where I wrote only time to slaughter trachea and esophagus as one, not one after the other; if so, there is valid shechitah time in less too: if there is half a defective trachea, behold time to slaughter esophagus majority and something of trachea is kosher shechitah; and if he paused such time, one may say it is shehiyah for valid shechitah time, for in such time shechitah can become valid — and we must be stringent; and this is the Gemara's question "he paused in minority of simanim": in truth he only slaughtered minority — majority of esophagus and something of trachea; but nevertheless there is reality the shechitah is valid — it is shehiyah; and it was beautifully doubtful; and this is what Rambam wrote "time to slaughter minority of simanim," namely in the above manner — and it comes out well and precise; for for practical law certainly correct. And truly Ran's words, who say we estimate time to cut skin — also we learn shechitah in order contradicts this; for if we are stringent, there is reality of half defective trachea, all the more reality skin tore beforehand. And in Rashba too, who wrote in responsum that cutting feathers does not combine — implies in skin he agrees to Ran; but from this there is no proof Rambam would not think as I said, for he explains another explanation on "he paused in minority of simanim." And Terumat HaDeshen at end of siman 185 wrote for Rashi: fowl shehiyah is measure of fowl shechitah; in defective half trachea, something suffices. Behold clear his view is as I said, and it is correct and clear like Rambam's words. One should be stringent, not like Ran.`,
  '4#_': `As the measure — and if he does not slaughter quickly, or his knife is not so fine — therefore he pauses in shechitah. If we estimate according to valid shechitah time, meaning according to his matter and his knife interest in another animal, or we do not watch him, only time for an expert with fine knife to slaughter — otherwise. At first glance the matter is doubtful. Nevertheless Tosafot explained the case "he paused in minority of simanim": he slaughtered with bad knife and slaughtered the entire siman; when he slaughtered majority, that siman's shechitah was already finished, and it is as cutting flesh in general; if so, this finishing the last minority before slaughtering the second siman — behold shehiyah; and it was resolved teiku. And we must say why it mentions slaughter with bad knife: if with fine knife, what of it that that minority is shehiyah? It is not measure of valid shechitah of majority; therefore it says bad knife and pauses more. If so, if one holds slaughter with bad knife — even valid shechitah measure in such case is still not shehiyah measure, for he only slaughtered minority and we require majority of siman with bad knife — we learn we do not follow fine-knife shehiyah measure when he slaughters with bad knife. If so, in any case even on this view the shehiyah measure nearly fell clearly; for possible expert with great alacrity and very sharp knife — measure very short. And truly still difficult in Tosafot: why do I need bad knife? Even fine knife — safek shehiyah in minority of siman applies; meaning he paused time — only not so much as valid shechitah measure. Nevertheless combine: he paused in slaughtering remaining minority of siman unnecessarily, as Tosafot wrote — behold complete shehiyah, and it is valid shechitah measure; and this is the safek in the Gemara; only Tosafot chose one of them — and it is simple.`,
  '5#_': `For all that shechitah is not finished, etc. — this is Tosafot's view; and it appears Rashi holds Torah invalidation, for from the outset he should act on rabbinic law; and also it should not make safek for stringency; however one may say it is safek teiku, forced. Main point: Tosafot challenged Rashi from Tosefta that it is valid, and what is the difficulty — perhaps it teaches Torah-valid?`,
});

// --- pitchei-teshuva (6) ---
patchFile('siman_023/pitchei-teshuva/part-001.txt', 'pitchei-teshuva', {
  '1#_': `<b>Until majority of simanim.</b> See Tiferet Lemoshe, who wrote: meaning it does not suffice with measure of shechitah of majority of simanim alone without skin over the simanim; therefore he wrote the word "until," for we require he slaughter skin and flesh until majority of simanim — see there.`,
  '2#_': `<b>And in fowl, in order to lift.</b> [See responsum Mishkenot Yaakov, siman 10, what is written on this.]`,
  '3#_': `<b>Even any amount.</b> Ba'er Heitev, seif kaf heh. And see Sefer Beit Lechem Yehudah, who wrote: if he slaughtered and at the time of shechitah the knife head touched the wall or ground — latter shechitah books write this is complete shehiyah — see there; and Teshuvat Beit Shmuel testified this is slaughterers' practice. And see responsum Makom Shmuel, siman 29, who raised that one should not be stringent at all; and it is obvious where he does not know when the knife touched wall or ground, whether before finishing shechitah or after — certainly kosher; and even Beit Lechem Yehudah concedes — see there. However, in responsum Zichron Yosef, part 4, siman 1, he is stringent: if the knife head was pushed at shechitah and touched the special wooden slaughter chair called "shraagin" — shechitah invalid; even if he does not know when it touched, before or after finishing — the custom spread among slaughterers to declare treifah unless clarified clearly he did not slaughter after the push; and they do not distinguish strong push from light push and touch; and it should not be like permitted matters, etc. (however according to this, specifically if slaughterers' custom is fence and safeguard; but if they practice prohibition because they think the law is so — permitted matters do not apply, as above siman 214, seif 1 — see there; also difficult: for in an uncommon matter custom does not apply, as Shach wrote below siman 190, seif kaf gimmel). And he further wrote: if the knife head was not pushed, only the butcher passed the knife point in holacha or hava'ah on the animal's neck and on the shraagin wood at once — even though there is concern he paused on the wood more than on the siman — nevertheless validate, since there is no shehiyah in any amount, neither Torah nor rabbinic prohibition, only from custom; therefore we say safek for leniency (and one must distinguish this from gomi found, where there is no safek at all, as Rama wrote "certainly he had to," etc.). And all the more when there is safek when it touched, before finishing shechitah or after; and especially if the slaughterer says "It is clear to me I did not pause at all" — see there at length.`,
  '4#_': `<b>And if after shechitah gomi is found.</b> See responsum Shevut Yaakov, part 2, siman 61, where they asked about a chicken whose slaughtered head comes from its mouth and they pulled it and saw it is inside the esophagus and did not come outside — how slaughter it? He answered: practice like the case of blood spurting — slaughter trachea alone; for even though l'chatchila one must slaughter two simanim in fowl, here it is b'dieved: if he slaughters esophagus he comes to shehiyah when he cuts the thread; and after shechitah they will see from where this thread came. And so they did, and found the slaughtered head was pulled through the esophagus to the crop and from there to the gizzard, and there was the knot of threads the chicken ate; no other defect was found — and he validated — see there at length.`,
  '5#_': `<b>Gomi.</b> Ba'er Heitev, seif kaf heh [he wrote in the name of Shach: and I did not know why Bach was lenient, etc.; and see responsum Mishkenot Yaakov, siman 12, who reconciles Bach's words — see there]. And that which he wrote in the name of Kenesset HaGedolah regarding esophagus with bran — see responsum Batei Kehunah, siman 10, asked similarly on a chicken after shechitah: pit in esophagus; he elaborated: specifically when a soft thing like gomi is found forbid; but if a hard thing like thorn, wheat, barley, or pit lying in esophagus was cut — kosher; this is Bach's reason permitting grass; and even Shach who disagreed — only regarding grass, for though not soft like the siman, nevertheless unlike the siman in hardness and firmness after stretching; but in other hard things that are like stretched and stand until they lean the siman to stretching — even Shach admits not to forbid; nevertheless he fears to rely practically after this distinction was not mentioned in any latter authority; but in safek whether it was cut — plainly certainly permit and rely on Kenesset HaGedolah, who permits even gomi in such case — see there, where he elaborated greatly. And that which he wrote in the name of Or Zarua regarding cutting his finger — see responsum Avnei Nezer, part 2, siman 42.`,
  '6#_': `<b>Or the like.</b> Chumdei Daniel wrote: sometimes hard blisters are found in fowl between siman and siman; if one was cut with the simanim — declare treifah because of shehiyah; but soft things around simanim — no concern. And he further wrote: where one fears in fowl lest something be found in esophagus, such as it just ate, etc. — permitted to slaughter one siman l'chatchila, for time of distress is like b'dieved — end of his words; and see above seif kaf gimmel.`,
});

// --- nekudot-hakesef (2) ---
patchFile('siman_023/nekudot-hakesef/part-001.txt', 'nekudot-hakesef', {
  '1#_': `<b>(Siman 23, Hagahah, Shach seif kaf gimmel) He paused the time of shechitah by a hair's breadth more, etc.</b> It implies: if he paused the time of lifting and laying down and a little shechitah, still needing much for majority — kosher; and it requires study why Rambam did not write this law; therefore it appears to Rambam: even if he paused the time of a little shechitah — even so the Gemara requires it, since the measure of shechitah is a small matter and a small measure is between slaughtering its majority and minority; therefore it must be asked whether it is treifah if he paused the time to lift, lay down, and slaughter somewhat; but if he paused less than this — meaning he did not pause the measure of all three, only paused the measure of lifting and laying down without shechitah, or vice versa — kosher; so it appears to me according to Rambam; and so is proven from commentators who challenged Rambam — for according to Beit Yosef's explanation there is no challenge here — end.`,
  '2#_': `<b>(There, Taz seif vav) And he was not precise — for certainly, etc.</b> In my humble opinion: the drop of blood that came out is because of the shechitah he slaughtered in that place; and from where would it occur to him to forbid? For there is no doubt here at all — only the place of shechitah is recognizable, and there is no hole at all.`,
});

// --- kaf-hachayim (6) ---
patchFile('siman_023/kaf-hachayim/part-001.txt', 'kaf-hachayim', {
  '1#_': `<b>(a) [Seif 1] Any slaughterer who does not know the five [laws] of shechitah, etc.</b> And these are shehiyah, etc.; and furthermore there are two other laws he must know: checking the knife and checking the simanim after shechitah, as written above siman 1, seif 2, in Hagahah — see there; and in our words to the name, b'siyata diShmaya.`,
  '2#_': `<b>(b) There. Forbidden to eat from his shechitah.</b> And even if afterward they ask him if he did such and such and he says "It is clear to me I slaughtered well" — his shechitah is invalid, since he does not know laws of shechitah, and perhaps he paused and pressed and does not feel — as written above siman 1, seif 3 — see there. Perishah, letter 1; Zivchei Tzedek, letter 1; Zivchei Tzedek, letter 2.`,
  '3#_': `<b>(c) And if</b> he slaughters before us in a manner we can check the place of shechitah and we saw he did not do hagramah; we also checked and saw the simanim were not uprooted; also he did not do chaladah, such as we saw the feather or hair cut, as in siman 3, seif 1 — even though we found him slaughtering who knows only the law of shehiyah and drasah — permitted to eat from his shechitah, for three laws exist in examination; and if we examined and found them proper — kosher; and we also checked the knife and it is fine. But if he lacked the law of drasah or shehiyah — in any case forbidden. Perishah, letter 2; Zivchei Tzedek, letter 2. But Shach, letter 1, disagreed with Perishah's words above, and wrote he must also know chaladah — see there. And so Minchat HaZahav, general rule 15 in Asheron, letter 2; and Zivchei Tzedek, letter 3, agreed — except what he wrote in Asheron that he must also know hagramah; and he disagreed with Shach — Zivchei Tzedek wrote there this is not so, for hagramah one knows well, such as where we see he slaughtered in the middle of the neck and the heads of the simanim are still before us in their quality and he did not touch them at all — see there.`,
  '4#_': `<b>(d) There. And these are shehiyah, etc.</b> And one should not ask reason for these laws, for all are halakhah leMoshe miSinai. Sha'arei Tzedek, letter 1; and one who is clever to give reason for these laws does not act properly, for damage may come from it, comparing matter to matter and thereby misleading the many. Turei Zahav, letter 1; Shach, letter 2; Asheron, letter 6; Chayei Adam, general rule 7, letter 1; Zivchei Tzedek, letter 4.`,
  '5#_': `<b>(e) [Seif 2] Shehiyah — how so: behold he began to slaughter and raised his hand, etc.</b> The same applies if he did not raise and paused — he mentioned it as ordinary way of speaking. Shach, seif kaf bet. Peri Chadash, letter 2; Kereti, letter 2; Sha'arei Tzedek, letter 2; Shach, letter 2; Zivchei Tzedek, letter 3; Chayei Adam there, letter 2; Zivchei Tzedek, letter 5.`,
  '6#_': `<b>(f) There. Shehiyah — how so, etc.</b> And shehiyah means language of delay, from language "the early pious ones would pause one hour," etc.; and it is holy language. Rashbatz. Zivchei Tzedek there.`,
});

// --- yad-avraham (1) ---
patchFile('siman_023/yad-avraham/part-001.txt', 'yad-avraham', {
  '1#_': `(Siman 23) Peri Megadim, seif kaf 8, was lenient in animal in Beit Meir regarding gomi found or cut on finger — only rabbinic shehiyah in any amount; only in fowl be stringent, unless at time of shechitah he did not feel he cut his finger — permit even in fowl, for it is safek safeka and safek in dispute helps even where there is presumption. And if esophagus full of bran, etc. — he permitted even in fowl; and see seif safek 34. And in responsum Panim Me'irot, part 2, he permits slaughter on finger, for it is stretched forcefully like the siman; and see responsum Zichron Yosef, part 4, on this.`,
});

// --- yad-ephraim (3) ---
patchFile('siman_023/yad-ephraim/part-001.txt', 'yad-ephraim', {
  '1#_': `<b>And it becomes shehiyah in any amount and treifah.</b> Ba'er Heitev. And he wrote in Shevut Yaakov, part 2, siman 54: hard thorn stuck between esophagus and trachea from outside — declare treifah; for that which Rama mentions regarding lying in esophagus speaks of what is normally found through eating — see there, where he wrote regarding a chicken with thread coming from its mouth, pulled, felt it goes outside — how slaughter? He answered: slaughter trachea alone; even though l'chatchila two simanim, here b'dieved: if he slaughters esophagus he comes to shehiyah when cutting the thread; after shechitah see from where it came and investigate. They did so; found slaughtered head pulled through esophagus to crop and gizzard, knot of threads the chicken ate; no defect — validated. And in Divrei Shalom, siman 236: slaughterer slaughtered fowl, soft thin grass leaf found cut in two — be stringent because of shehiyah, as Shach wrote — see there. And in Ba'er Heitev, what he wrote in name of Or Zarua, siman 86 — textual error, should read tzadi vav; and what he wrote that for kashering utensils he leaned lenient — not so: he wrote those utensils may be kashered, but if mixture increased in those utensils they again used other utensils — no kashering needed — see there. And see what he wrote in name of Beit Yosef on cut of holder's finger; and so in Avnei Nezer, part 2, siman 42: one slaughtered fowl, friend held fowl at shechitah and also cut finger — validate, as we say in Chullin, daf 32: slaughtered cow and cut pomegranate with it — kosher; even though one may say specifically for them who require shehiyah measure, not for us forbidden like gomi found along neck length, not stretched, and knife sharpness pauses to cut it more than cutting siman — not so human finger holding forcefully: one may say cut esophagus and finger at once, cutting both equally — therefore I permitted — see there. And Zichron Yosef, siman 1: slaughterer slaughtered calf on special slaughter chair called shraagin; felt at shechitah knife touched shraagin wood during shechitah, but said "It is clear I did not pause at all, nor startled at touch, nor cut wood, only touch"; with extra honor checked wood — no cut; from speed of shechitah did not know if before or after finishing — he answered: even though Or Zarua, siman 66, wrote we do not judge safek shehiyah like other shechitah doubts, etc.; and also per Chinuch, Beit Yosef, siman 24, law if knife head pushed to wall or hard ground — shechitah invalid — one might say do not add; specifically pushed at shechitah, not in safek; nevertheless custom among slaughterers to declare treifah unless clarified clearly he did not slaughter after push; they do not distinguish light touch; and since he did not intend to finish shechitah, it is habitual from speed not to interrupt shechitah only to complete his act — not called safek if slaughtered after push; nevertheless he raised it is kosher since safek whether he cut or only touched without cutting and shehiyah — safek for leniency. And all the more in our case there is safek safeka, and also permission because he says "It is clear"; and even though in gomi found they declare treifah because there he errs thinking he paused cutting siman but actually paused cutting gomi; and so cutting finger from panic — sense testifies he certainly raised knife somewhat; and we can say same for knife head touching wall or hard ground — not so in our case: we can say since he knows shechitah laws and says "It is clear I did not pause" — we say certainly he did not cut wood and shechitah kosher — see there.`,
  '2#_': `<b>Strike on its head to kill it.</b> Ba'er Heitev. And see Tosafot Yom Tov in the name of Sha'arei Tzedek; and what Ba'er Heitev wrote in the name of Divrei Shmuel, siman 37 — textual error, should read 237; and they brought it in Likutei HaKadmonim. And see Beit Yaakov, siman 138; and Shevut Yaakov, part 2, siman 54: slaughterer slaughtered chicken, slaughtered entire trachea, gave fowl from his hand while presumed kosher; when brought home still alive, running as usual; ordered household member to cut esophagus in two so it dies; cut with flawed knife — forbid because of shehiyah and ikkur in last minority or not? Shach in siman 23, seif kaf 13, challenges R' Tzvi on this; and it appears to me to decide: certainly l'chatchila forbidden to do so; b'dieved, even though from Shach's words it implies forbid b'dieved, I do not think so at all: once slaughterer removed his hand completely from shechitah after slaughtering majority and it is called valid shechitah name on him — if afterward fowl pauses to die, do not invalidate b'dieved if he completes its death with flawed knife, since it already left slaughterer's hand in valid shechitah name — do not declare treifah further because of shehiyah. Such incident came regarding a sick person: they slaughtered fowl for him, slaughtered esophagus and trachea whole, still alive as before; I ordered leave until dies by itself, perhaps atonement for the sick; as long as chicken lived, sick lived; until one came and chopped its head — patient became moribund; as long as chicken convulsed, his soul did not depart — see there. And Meir Netivim, siman 17, on indik fowl wanting to be lenient: if clear to slaughterer one siman already completely slaughtered and he did not begin the second — permitted to chop head with axe; no concern of shehiyah in last minority, only where majority of simanim slaughtered — error in his hand; and explicitly Semak, siman 196 — heaven forbid to be lenient thus.`,
  '3#_': `<b>And I do not know if esophagus was perforated.</b> Ba'er Heitev. And Shevut Yaakov, part 2, siman 65: slaughterer began slaughtering animal, slaughtered part of skin, paused, slaughtered afterward elsewhere; place first cut was washed well, checked, saw skin not entirely cut — if no blood, lenient plainly; but even if blood — lenient as Peri Chadash, seif 23: not like plucking feathers, for fowl skin is thin unlike animal skin where examination can stand; nevertheless not fitting for every slaughterer to do so — only ask teacher or join other expert slaughterers.`,
});

